package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var inputDone bool

var taxFileScanner *bufio.Scanner
var taxFile *os.File

func formatNumericEdited(pic string, val decimal.Decimal) string {
	// Handle sign: all values non-negative in this program, but handle generically
	negative := val.Sign() < 0
	if negative {
		val = val.Abs()
	}
	// Extract integer and fractional parts
	// val has scale 2 for this program, but be generic based on pic
	// Count fractional digit slots after '.'
	dotIdx := strings.Index(pic, ".")
	var fracSlots int
	var intSlots int
	if dotIdx >= 0 {
		for i := dotIdx + 1; i < len(pic); i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				fracSlots++
			}
		}
		for i := 0; i < dotIdx; i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				intSlots++
			}
		}
	} else {
		for i := 0; i < len(pic); i++ {
			if pic[i] == 'Z' || pic[i] == '9' {
				intSlots++
			}
		}
	}

	// Get integer part and fractional part as strings with proper scale
	// We need integer part = trunc(val) and fractional = remainder
	// Use Shift to avoid float
	// For general fracSlots, we format val to fracSlots decimal places truncated? But MOVE to edited does rounding? Actually MOVE truncates? In COBOL numeric-edited MOVE uses value as is.
	// Here values already have scale 2, so we just format.
	// Ensure val is truncated to fracSlots (not rounded) ? COBOL MOVE to edited does not round, it just formats. But values already at correct scale.
	// So we will truncate towards zero to fracSlots.
	valTrunc := val.Truncate(int32(fracSlots))

	// Split
	// Use string representation with fixed fracSlots
	s := valTrunc.StringFixed(int32(fracSlots)) // e.g. "1000.00" or "1000" if fracSlots 0
	var intStr, fracStr string
	if fracSlots > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracSlots)
		}
		// handle negative sign already removed
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
	} else {
		intStr = s
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		fracStr = ""
	}
	// Drop high-order digits if overflow
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// Pad intStr to intSlots with leading zeros
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}
	// Pad fracStr to fracSlots
	if len(fracStr) < fracSlots {
		fracStr = fracStr + strings.Repeat("0", fracSlots-len(fracStr))
	}
	if len(fracStr) > fracSlots {
		fracStr = fracStr[:fracSlots]
	}

	// Build output array
	out := make([]byte, len(pic))
	intIdx := 0
	fracIdx := 0
	for i := 0; i < len(pic); i++ {
		c := pic[i]
		switch c {
		case 'Z', '9':
			// determine if before dot or after
			if dotIdx >= 0 && i > dotIdx {
				out[i] = fracStr[fracIdx]
				fracIdx++
			} else if dotIdx >= 0 && i < dotIdx {
				out[i] = intStr[intIdx]
				intIdx++
			} else if dotIdx == -1 {
				out[i] = intStr[intIdx]
				intIdx++
			} else {
				// dot itself not here
				out[i] = byte(c)
			}
		case ',':
			out[i] = ','
		case '.':
			out[i] = '.'
		default:
			out[i] = byte(c)
		}
	}

	// Apply zero suppression for integer part
	sup := true
	for i := 0; i < len(pic); i++ {
		c := pic[i]
		if c == 'Z' || c == '9' {
			if dotIdx >= 0 && i > dotIdx {
				// fractional part: no suppression
				sup = false
				continue
			}
			if sup {
				if c == 'Z' && out[i] == '0' {
					out[i] = ' '
				} else {
					// non-zero or 9
					sup = false
				}
			}
		} else if c == ',' {
			if sup {
				out[i] = ' '
			}
		} else if c == '.' {
			// decimal point ends suppression zone, but keep it
			sup = false
		}
	}

	// Sign handling not needed for this program

	return string(out)
}

func MAIN_PARA() {
	taxFile, err := os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty
		if os.IsNotExist(err) {
			inputDone = true
			WsEofFlag = "Y"
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		defer taxFile.Close()
		taxFileScanner = bufio.NewScanner(taxFile)
	}
	if !inputDone {
		READ_PARA()
		for !inputDone {
			PROCESS_PARA()
		}
		if taxFile != nil {
			taxFile.Close()
		}
	}
	WsTotalEd = formatNumericEdited("ZZ,ZZZ,ZZ9.99", WsTotalTax)
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	// WS-COUNT is PIC 9(3) unedited numeric: DISPLAY zero-padded to 3? But program DISPLAYs it directly.
	// However spec says unedited numeric DISPLAY prints zero-padded to digit count.
	// But here code DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	// So WS-COUNT should be formatted as 3 digits zero-padded.
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func READ_PARA() {
	if taxFileScanner == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	if !taxFileScanner.Scan() {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := taxFileScanner.Text()
	// Pad with spaces to 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	// Parse TR-ID @0 len 5
	taxRec.TrId = line[0:5]
	// Parse TR-INCOME @5 len 8 digits with implied V99
	raw := line[5 : 5+8]
	raw = strings.TrimSpace(raw)
	if raw == "" {
		raw = "0"
	}
	// raw should be digits; parse integer
	// Allow possible leading zeros
	// decimal.New requires int64; value may be up to 99999999 fits int64
	var n int64
	// raw may contain spaces? already trimmed, but if contains non-digit keep?
	// parse digits only
	clean := ""
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		clean = "0"
	}
	// Use decimal from string to avoid int64 overflow? It's 8 digits fits.
	fmt.Sscanf(clean, "%d", &n)
	taxRec.TrIncome = decimal.New(n, -2)
}

func PROCESS_PARA() {
	tenThousand := decimal.NewFromInt(10000)
	fortyThousand := decimal.NewFromInt(40000)
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)
	rate10 := decimal.NewFromFloat(0.10)
	rate20 := decimal.NewFromFloat(0.20)
	rate30 := decimal.NewFromFloat(0.30)

	if taxRec.TrIncome.Cmp(decimal.NewFromInt(10000)) <= 0 {
		// COMPUTE WS-TAX ROUNDED = TR-INCOME * 0.10
		computed := taxRec.TrIncome.Mul(rate10)
		WsTax = computed.Round(2)
	} else {
		if taxRec.TrIncome.Cmp(fortyThousand) <= 0 {
			computed := thousand.Add(taxRec.TrIncome.Sub(tenThousand).Mul(rate20))
			WsTax = computed.Round(2)
		} else {
			computed := sevenThousand.Add(taxRec.TrIncome.Sub(fortyThousand).Mul(rate30))
			WsTax = computed.Round(2)
		}
	}
	// Enforce storage in PIC 9(7)V99 truncation to 2 and high-order drop (value fits)
	WsTax = WsTax.Truncate(2)
	// COMPUTE WS-NET = TR-INCOME - WS-TAX
	WsNet = taxRec.TrIncome.Sub(WsTax).Truncate(2)
	// ADD WS-TAX TO WS-TOTAL-TAX
	WsTotalTax = WsTotalTax.Add(WsTax).Truncate(2)
	// ADD 1 TO WS-COUNT
	WsCount++
	// MOVE TR-INCOME TO WS-INC-ED etc.
	WsIncEd = formatNumericEdited("ZZZ,ZZ9.99", taxRec.TrIncome)
	WsTaxEd = formatNumericEdited("ZZZ,ZZ9.99", WsTax)
	WsNetEd = formatNumericEdited("ZZZ,ZZ9.99", WsNet)
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	READ_PARA()
}

func main() {
	MAIN_PARA()
}
